import React from 'react'
import { Card } from 'react-bootstrap';


const Recipe=({title, description})=>{
    return(
        <Card>
            <Card.Body>
            <Card.Title>{title}</Card.Title>
            <p>{description}</p>
            </Card.Body>
        </Card>
    )
}

export default Recipe;
